    @inline(__always)
    private func checkSlideMask1UpConstantMask(_ mask: H.Mask) {
        let mismatches = Mismatches("slideMask1Up with mask \(describe(mask))")
        mismatches.check(
            H.slide1Up(mask),
            H.Mask(raw: HighwayReference.slideMask1UpU32(mask.raw)),
            ""
        )
        mismatches.record()
    }

    @Test func slideMask1UpConstantMaskAllFalse() {
        checkSlideMask1UpConstantMask(H.Mask(H.Mask.SIMDType(repeating: false)))
    }

    @Test func slideMask1UpConstantMaskAllTrue() {
        checkSlideMask1UpConstantMask(H.Mask(H.Mask.SIMDType(repeating: true)))
    }

    @Test func slideMask1UpConstantMaskOnlyFirst() {
        checkSlideMask1UpConstantMask(
